import { canonicalDigest } from "@chainlesschain/context-memory-kernel";
import {
  CONTEXT_WINDOWS,
  DOCUMENTED_OPENAI_MODELS,
  DOCUMENTED_ANTHROPIC_MODELS,
  LEGACY_MODEL_PROVIDERS,
  MODEL_CAPABILITY_CATALOG_VERSION,
} from "./model-context-catalog.js";
import { mergeProviderOptions } from "./provider-options.js";

const PROFILE_SCHEMA = "chainlesschain.model-capability-profile/v1";
const MAX_CONTEXT_WINDOW_TOKENS = 16_777_216;
const CHAT_COMPLETIONS_PROVIDERS = new Set([
  "openai",
  "deepseek",
  "dashscope",
  "mistral",
  "gemini",
  "volcengine",
]);

function optionalIdentity(value, field) {
  if (value == null || value === "") return null;
  if (typeof value !== "string" || value.length > 256) {
    throw new TypeError(`${field} must be a string of at most 256 characters`);
  }
  if (/\p{Cc}/u.test(value)) {
    throw new TypeError(`${field} must not contain control characters`);
  }
  // Provider/model identity is exact, just like the request transport. Do not
  // certify an alias by trimming or changing the case of an actual request id.
  return value;
}

function optionalPositiveInteger(
  value,
  field,
  { min = 1, max = Number.MAX_SAFE_INTEGER } = {},
) {
  if (value == null) return null;
  const normalized =
    typeof value === "string" && /^\d+$/u.test(value.trim())
      ? Number(value.trim())
      : value;
  if (
    typeof normalized !== "number" ||
    !Number.isSafeInteger(normalized) ||
    normalized < min ||
    normalized > max
  ) {
    throw new RangeError(
      `${field} must be an integer between ${min} and ${max}`,
    );
  }
  return normalized;
}

function deepFreeze(value) {
  for (const child of Object.values(value)) {
    if (child && typeof child === "object") deepFreeze(child);
  }
  return Object.freeze(value);
}

function isOfficialModelBaseUrl(provider, baseUrl) {
  if (baseUrl == null || baseUrl === "") return true;
  if (typeof baseUrl !== "string") {
    throw new TypeError("baseUrl must be a string when provided");
  }
  try {
    // Deliberately excludes credentials, paths other than /v1, query/hash
    // decorations and non-default ports. Never return or hash the input URL.
    return (
      baseUrl === baseUrl.trim() &&
      new URL(baseUrl).href ===
        (provider === "openai"
          ? "https://api.openai.com/v1"
          : "https://api.anthropic.com/v1")
    );
  } catch {
    return false;
  }
}

/**
 * Describe the output cap the existing agent transport actually sends.
 * This does not add a cap to Chat Completions/Ollama or select a new model.
 * The planner may apply its own minimum reserve and reject an impossible
 * input/output allocation; no context-window clipping happens here.
 */
export function resolveAgentOutputBudget({
  provider,
  model,
  maxOutputTokens,
} = {}) {
  const requested = optionalPositiveInteger(maxOutputTokens, "maxOutputTokens");
  if (provider === "anthropic") {
    const effectiveModel = model || "claude-sonnet-4-6";
    const { maxTokens } = mergeProviderOptions("anthropic", effectiveModel);
    const defaultCap = maxTokens || 8192;
    const requestMaxOutputTokens =
      requested === null ? defaultCap : Math.min(defaultCap, requested);
    return Object.freeze({
      requestMaxOutputTokens,
      plannedOutputReserveTokens: requestMaxOutputTokens,
      outputReserveSource:
        requested === null
          ? "anthropic-request-default"
          : requested > defaultCap
            ? "anthropic-request-clamp"
            : "explicit-request-cap",
    });
  }
  return Object.freeze({
    requestMaxOutputTokens: requested,
    plannedOutputReserveTokens: requested ?? 4096,
    outputReserveSource:
      requested === null ? "planning-fallback" : "explicit-request-cap",
  });
}

/**
 * Pure, versioned diagnostics/planning projection. No provider discovery,
 * credential loading, model calls or protocol negotiation is performed.
 * `runtimeVerified:false` applies even to documented model specifications.
 */
export function resolveModelCapabilityProfile({
  provider,
  model,
  baseUrl,
  contextMemoryModelWindowTokens,
  maxOutputTokens,
} = {}) {
  const selectedProvider = optionalIdentity(provider, "provider");
  const selectedModel = optionalIdentity(model, "model");
  if (baseUrl != null && typeof baseUrl !== "string") {
    throw new TypeError("baseUrl must be a string when provided");
  }
  const override = optionalPositiveInteger(
    contextMemoryModelWindowTokens,
    "contextMemoryModelWindowTokens",
    { min: 1024, max: MAX_CONTEXT_WINDOW_TOKENS },
  );
  const catalog =
    selectedProvider === "openai"
      ? DOCUMENTED_OPENAI_MODELS
      : selectedProvider === "anthropic"
        ? DOCUMENTED_ANTHROPIC_MODELS
        : null;
  const officialEndpoint =
    Boolean(catalog) && isOfficialModelBaseUrl(selectedProvider, baseUrl);
  const documented =
    officialEndpoint && selectedModel && Object.hasOwn(catalog, selectedModel)
      ? catalog[selectedModel]
      : null;
  const legacyOwner =
    selectedModel && Object.hasOwn(LEGACY_MODEL_PROVIDERS, selectedModel)
      ? LEGACY_MODEL_PROVIDERS[selectedModel]
      : null;
  let contextWindowTokens;
  let windowSource;
  let windowAssumed = true;
  if (override !== null) {
    contextWindowTokens = override;
    windowSource = "explicit-override";
  } else if (documented) {
    contextWindowTokens = documented.contextWindowTokens;
    windowSource = "official-model-docs";
    windowAssumed = false;
  } else if (
    legacyOwner &&
    (!selectedProvider || legacyOwner === selectedProvider)
  ) {
    contextWindowTokens = CONTEXT_WINDOWS[selectedModel];
    windowSource = selectedProvider
      ? "legacy-catalog"
      : "legacy-catalog-unscoped";
  } else if (
    selectedProvider &&
    Object.hasOwn(CONTEXT_WINDOWS._provider_defaults, selectedProvider)
  ) {
    contextWindowTokens = CONTEXT_WINDOWS._provider_defaults[selectedProvider];
    windowSource = "provider-default";
  } else {
    contextWindowTokens = 32768;
    windowSource = "generic-default";
  }

  const output = resolveAgentOutputBudget({
    provider: selectedProvider,
    model: selectedModel,
    maxOutputTokens,
  });
  const runtimeProtocol =
    selectedProvider === "ollama"
      ? "ollama-chat"
      : selectedProvider === "anthropic"
        ? "anthropic-messages"
        : selectedProvider === "openai" && documented?.requiresResponsesForTools
          ? "openai-responses"
          : CHAT_COMPLETIONS_PROVIDERS.has(selectedProvider) || Boolean(baseUrl)
            ? "chat-completions"
            : "unsupported";
  const limitations = [
    "Runtime execution, endpoint access and account entitlement have not been verified.",
  ];
  if (windowSource === "explicit-override") {
    limitations.push("The context window is operator-declared and unverified.");
  } else if (windowAssumed) {
    limitations.push(
      "The context window is a legacy or fallback planning estimate, not a verified model limit.",
    );
  }
  if (!selectedProvider) {
    limitations.push(
      "No provider was specified; an unscoped legacy model lookup does not establish provider capabilities.",
    );
  }
  if (legacyOwner && selectedProvider && legacyOwner !== selectedProvider) {
    limitations.push(
      "The model's legacy catalog entry belongs to another provider and was not applied.",
    );
  }
  if (catalog && !officialEndpoint) {
    limitations.push(
      `Official ${selectedProvider === "openai" ? "OpenAI" : "Anthropic"} model specifications are not applied to a custom endpoint.`,
    );
  }
  if (output.requestMaxOutputTokens === null) {
    limitations.push(
      "The output reserve is a planning fallback, not an output cap sent to the provider.",
    );
  }
  if (documented?.requiresResponsesForTools) {
    limitations.push(
      "Responses selection is based on the versioned catalog and has not been verified against this account at runtime.",
    );
  }
  if (runtimeProtocol === "unsupported") {
    limitations.push(
      "No supported agent transport was resolved for this provider and endpoint configuration.",
    );
  }
  if (
    documented?.advertisedMaxOutputTokens != null &&
    output.requestMaxOutputTokens > documented.advertisedMaxOutputTokens
  ) {
    limitations.push(
      "The requested output cap exceeds the documented model maximum; the profile does not rewrite the request.",
    );
  }

  const identityDigest = canonicalDigest(
    {
      schema: PROFILE_SCHEMA,
      provider: selectedProvider || "unknown",
      model: selectedModel,
    },
    "chainlesschain.model-capability-identity/v1",
  );
  const profile = {
    schema: PROFILE_SCHEMA,
    catalogVersion: MODEL_CAPABILITY_CATALOG_VERSION,
    profileId: `model-capability-v1:${identityDigest.slice(7, 39)}`,
    provider: selectedProvider || "unknown",
    model: selectedModel,
    contextWindowTokens,
    windowSource,
    windowAssumed,
    runtimeProtocol,
    runtimeVerified: false,
    ...output,
    advertisedMaxOutputTokens: documented?.advertisedMaxOutputTokens ?? null,
    ...(documented?.reasoningEfforts
      ? { reasoningEfforts: [...documented.reasoningEfforts] }
      : {}),
    sources: documented ? [...documented.sources] : [],
    limitations,
  };
  profile.digest = canonicalDigest(profile, PROFILE_SCHEMA);
  return deepFreeze(profile);
}

import { describe, expect, it } from "vitest";
import { canonicalDigest } from "@chainlesschain/context-memory-kernel";
import {
  resolveAgentOutputBudget,
  resolveModelCapabilityProfile,
} from "../../src/lib/model-capabilities.js";
import {
  CONTEXT_WINDOWS as CATALOG_WINDOWS,
  DOCUMENTED_OPENAI_MODELS,
  LEGACY_MODEL_PROVIDERS,
} from "../../src/lib/model-context-catalog.js";
import {
  CONTEXT_WINDOWS,
  getContextWindow,
} from "../../src/lib/model-context-window.js";

describe("versioned model capability profiles", () => {
  it("reports the documented official model window without claiming live verification", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-4o",
    });
    expect(profile).toMatchObject({
      schema: "chainlesschain.model-capability-profile/v1",
      catalogVersion: "2026-09-27",
      provider: "openai",
      model: "gpt-4o",
      contextWindowTokens: 128000,
      windowSource: "official-model-docs",
      windowAssumed: false,
      runtimeProtocol: "chat-completions",
      runtimeVerified: false,
      requestMaxOutputTokens: null,
      plannedOutputReserveTokens: 4096,
      outputReserveSource: "planning-fallback",
      advertisedMaxOutputTokens: 16384,
      sources: ["https://developers.openai.com/api/docs/models/gpt-4o"],
    });
    expect(profile.limitations.join(" ")).toMatch(/not an output cap/);
  });

  it("selects native Responses for the documented official tool target", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra",
      baseUrl: "https://api.openai.com/v1",
    });
    expect(profile.contextWindowTokens).toBe(1050000);
    expect(profile.advertisedMaxOutputTokens).toBe(128000);
    expect(profile.runtimeProtocol).toBe("openai-responses");
    expect(profile.runtimeVerified).toBe(false);
    expect(profile.limitations.join(" ")).toMatch(/has not been verified/);
    expect(profile.limitations.join(" ")).not.toMatch(/not implemented/);
    expect(profile.sources).toContain(
      "https://developers.openai.com/api/docs/guides/migrate-to-responses",
    );
    expect(CONTEXT_WINDOWS).not.toHaveProperty("gpt-6-astra");
  });

  it.each([
    "https://gateway.example/v1",
    "http://api.openai.com/v1",
    "https://api.openai.com:444/v1",
    "https://api.openai.com/v1/",
    "https://api.openai.com/v1/other",
    "https://api.openai.com/v1?token=secret-marker",
    "https://api.openai.com/v1#secret-marker",
    "https://api.openai.com/v1#",
    "https://api.openai.com/v1 ",
    "https://user:secret-marker@api.openai.com/v1",
    "https://api.openai.com.example/v1",
    "not-a-url",
  ])("does not apply new official limits to custom endpoint %s", (baseUrl) => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra",
      baseUrl,
    });
    expect(profile.contextWindowTokens).toBe(128000);
    expect(profile.windowSource).toBe("provider-default");
    expect(profile.windowAssumed).toBe(true);
    expect(profile.advertisedMaxOutputTokens).toBeNull();
    expect(profile.sources).toEqual([]);
    expect(JSON.stringify(profile)).not.toContain(baseUrl);
    expect(JSON.stringify(profile)).not.toContain("secret-marker");
  });

  it("retains a custom gateway's old catalog value as assumed, not official", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-4o",
      baseUrl: "https://gateway.example/v1",
    });
    expect(profile.contextWindowTokens).toBe(128000);
    expect(profile.windowSource).toBe("legacy-catalog");
    expect(profile.windowAssumed).toBe(true);
    expect(profile.advertisedMaxOutputTokens).toBeNull();
  });

  it("does not infer arbitrary aliases or future snapshots from a prefix", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra-custom",
    });
    expect(profile.windowSource).toBe("provider-default");
    expect(profile.contextWindowTokens).toBe(128000);
    expect(profile.sources).toEqual([]);
  });

  it("keeps provider and model identities exact rather than rewriting request ids", () => {
    for (const model of [" gpt-6-astra", "gpt-6-astra ", "GPT-6-ASTRA"]) {
      expect(
        resolveModelCapabilityProfile({ provider: "openai", model })
          .windowSource,
      ).toBe("provider-default");
    }
    expect(
      resolveModelCapabilityProfile({
        provider: " openai",
        model: "gpt-6-astra",
      }).windowSource,
    ).toBe("generic-default");
  });

  it("isolates model catalog windows by explicit provider", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "ollama",
      model: "gpt-4o",
    });
    expect(profile.contextWindowTokens).toBe(32768);
    expect(profile.windowSource).toBe("provider-default");
    expect(profile.windowAssumed).toBe(true);
    expect(profile.runtimeProtocol).toBe("ollama-chat");
    expect(profile.limitations.join(" ")).toMatch(/another provider/);
    expect(getContextWindow("gpt-4o", "ollama")).toBe(32768);
  });

  it("keeps the no-provider legacy lookup explicitly unscoped", () => {
    expect(resolveModelCapabilityProfile({ model: "gpt-4o" })).toMatchObject({
      provider: "unknown",
      contextWindowTokens: 128000,
      windowSource: "legacy-catalog-unscoped",
      windowAssumed: true,
      runtimeProtocol: "unsupported",
      runtimeVerified: false,
    });
    expect(getContextWindow("gpt-4o")).toBe(128000);
  });

  it("does not choose a default model for an incomplete diagnostic target", () => {
    expect(resolveModelCapabilityProfile()).toMatchObject({
      provider: "unknown",
      model: null,
      contextWindowTokens: 32768,
      windowSource: "generic-default",
      windowAssumed: true,
    });
    expect(resolveModelCapabilityProfile({ provider: "openai" })).toMatchObject(
      {
        model: null,
        contextWindowTokens: 128000,
        windowSource: "provider-default",
      },
    );
  });

  it("never treats prototype property names as catalog records", () => {
    for (const model of [
      "__proto__",
      "constructor",
      "toString",
      "_provider_defaults",
    ]) {
      expect(
        resolveModelCapabilityProfile({ model, provider: "openai" })
          .windowSource,
      ).toBe("provider-default");
    }
    expect(
      resolveModelCapabilityProfile({ provider: "toString", model: "gpt-4o" })
        .contextWindowTokens,
    ).toBe(32768);
  });

  it("validates and identifies operator overrides without certifying them", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra",
      contextMemoryModelWindowTokens: " 8192 ",
    });
    expect(profile).toMatchObject({
      contextWindowTokens: 8192,
      windowSource: "explicit-override",
      windowAssumed: true,
    });
    expect(profile.limitations.join(" ")).toMatch(
      /operator-declared and unverified/,
    );
    expect(
      resolveModelCapabilityProfile({ contextMemoryModelWindowTokens: 1024 })
        .contextWindowTokens,
    ).toBe(1024);
    expect(
      resolveModelCapabilityProfile({
        contextMemoryModelWindowTokens: 16777216,
      }).contextWindowTokens,
    ).toBe(16777216);
  });

  it.each([
    0,
    -1,
    1023,
    16777217,
    NaN,
    Infinity,
    1024.5,
    true,
    false,
    "",
    "1e5",
    "1024.0",
    "secret-marker",
  ])(
    "rejects an invalid window override instead of silently using a fallback: %s",
    (value) => {
      expect(() =>
        resolveModelCapabilityProfile({
          contextMemoryModelWindowTokens: value,
        }),
      ).toThrow(/contextMemoryModelWindowTokens must be an integer/);
      try {
        resolveModelCapabilityProfile({
          contextMemoryModelWindowTokens: value,
        });
      } catch (error) {
        expect(error.message).not.toContain("secret-marker");
      }
    },
  );

  it("binds stable resolved values and provenance into a content digest", () => {
    const input = { provider: "openai", model: "gpt-6-astra" };
    const first = resolveModelCapabilityProfile(input);
    const second = resolveModelCapabilityProfile({ ...input });
    expect(second).toEqual(first);
    const { digest, ...payload } = first;
    expect(digest).toBe(canonicalDigest(payload, payload.schema));
    expect(first.profileId.length).toBeLessThan(128);
    expect(
      resolveModelCapabilityProfile({
        ...input,
        contextMemoryModelWindowTokens: 8192,
      }).digest,
    ).not.toBe(digest);
    expect(
      resolveModelCapabilityProfile({ ...input, maxOutputTokens: 8192 }).digest,
    ).not.toBe(digest);
    expect(
      resolveModelCapabilityProfile({
        ...input,
        baseUrl: "https://gateway.example/v1",
      }).digest,
    ).not.toBe(digest);
    expect(
      resolveModelCapabilityProfile({ ...input, provider: "ollama" }).profileId,
    ).not.toBe(first.profileId);
  });

  it("does not include endpoint credentials or transient host state in a digest", () => {
    const first = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra",
      baseUrl: "https://user:one@gateway.example/v1",
    });
    const second = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra",
      baseUrl: "https://user:two@other.example/v1",
    });
    expect(second.digest).toBe(first.digest);
    expect(JSON.stringify(first)).not.toMatch(
      /gateway\.example|user:one|baseUrl|apiKey|resolvedAt/,
    );
  });

  it("freezes and copies metadata so a caller cannot contaminate another profile", () => {
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-6-astra",
    });
    expect(Object.isFrozen(profile)).toBe(true);
    expect(Object.isFrozen(profile.sources)).toBe(true);
    expect(Object.isFrozen(profile.limitations)).toBe(true);
    expect(profile.sources).not.toBe(
      DOCUMENTED_OPENAI_MODELS["gpt-6-astra"].sources,
    );
    expect(() => profile.sources.push("changed")).toThrow(TypeError);
    expect(() => {
      profile.contextWindowTokens = 1;
    }).toThrow(TypeError);
    expect(
      resolveModelCapabilityProfile({
        provider: "openai",
        model: "gpt-6-astra",
      }),
    ).toEqual(profile);
  });
});

describe("agent output budget matches existing transport behavior", () => {
  it.each([
    [undefined, 8192],
    ["claude-sonnet-4-6", 8192],
    ["claude-opus-4-6", 16384],
    ["claude-haiku-4-5", 4096],
  ])("uses the existing Anthropic default for %s", (model, cap) => {
    expect(resolveAgentOutputBudget({ provider: "anthropic", model })).toEqual({
      requestMaxOutputTokens: cap,
      plannedOutputReserveTokens: cap,
      outputReserveSource: "anthropic-request-default",
    });
  });

  it("retains the Anthropic explicit-cap clamp and exposes it to the planner", () => {
    expect(
      resolveAgentOutputBudget({
        provider: "anthropic",
        model: "claude-opus-4-6",
        maxOutputTokens: 30000,
      }),
    ).toEqual({
      requestMaxOutputTokens: 16384,
      plannedOutputReserveTokens: 16384,
      outputReserveSource: "anthropic-request-clamp",
    });
    expect(
      resolveAgentOutputBudget({
        provider: "anthropic",
        maxOutputTokens: "512",
      }),
    ).toEqual({
      requestMaxOutputTokens: 512,
      plannedOutputReserveTokens: 512,
      outputReserveSource: "explicit-request-cap",
    });
  });

  it.each(["openai", "ollama", "deepseek", "custom", undefined])(
    "does not synthesize a request cap for %s",
    (provider) => {
      expect(resolveAgentOutputBudget({ provider })).toEqual({
        requestMaxOutputTokens: null,
        plannedOutputReserveTokens: 4096,
        outputReserveSource: "planning-fallback",
      });
    },
  );

  it("does not clip a requested cap or impose the planner's minimum reserve", () => {
    expect(
      resolveAgentOutputBudget({ provider: "openai", maxOutputTokens: 1 }),
    ).toMatchObject({
      requestMaxOutputTokens: 1,
      plannedOutputReserveTokens: 1,
    });
    const profile = resolveModelCapabilityProfile({
      provider: "openai",
      model: "gpt-4o",
      maxOutputTokens: 20000,
      contextMemoryModelWindowTokens: 1024,
    });
    expect(profile.requestMaxOutputTokens).toBe(20000);
    expect(profile.plannedOutputReserveTokens).toBe(20000);
    expect(profile.limitations.join(" ")).toMatch(
      /exceeds the documented model maximum/,
    );
  });

  it.each([null, undefined])(
    "treats only nullish caps as absent: %s",
    (maxOutputTokens) => {
      expect(
        resolveAgentOutputBudget({ maxOutputTokens }).requestMaxOutputTokens,
      ).toBeNull();
    },
  );

  it.each([
    0,
    -1,
    NaN,
    Infinity,
    1.5,
    true,
    false,
    "",
    "1e3",
    "1.5",
    "secret-marker",
    Number.MAX_SAFE_INTEGER + 1,
  ])("rejects an invalid explicit output cap: %s", (maxOutputTokens) => {
    expect(() => resolveAgentOutputBudget({ maxOutputTokens })).toThrow(
      /maxOutputTokens must be an integer/,
    );
  });
});

describe("legacy context window interface", () => {
  it("reexports the unchanged frozen catalog object", () => {
    expect(CONTEXT_WINDOWS).toBe(CATALOG_WINDOWS);
    expect(Object.isFrozen(CONTEXT_WINDOWS)).toBe(true);
    expect(Object.isFrozen(CONTEXT_WINDOWS._provider_defaults)).toBe(true);
    expect(Object.keys(CONTEXT_WINDOWS)).toHaveLength(31);
    for (const [model, provider] of Object.entries(LEGACY_MODEL_PROVIDERS)) {
      expect(getContextWindow(model, provider)).toBe(CONTEXT_WINDOWS[model]);
      expect(getContextWindow(model)).toBe(CONTEXT_WINDOWS[model]);
    }
  });

  it("retains provider and generic fallback numeric behavior", () => {
    expect(getContextWindow("unknown-model", "anthropic")).toBe(200000);
    expect(getContextWindow(null, "openai")).toBe(128000);
    expect(getContextWindow(undefined, "deepseek")).toBe(64000);
    expect(getContextWindow("", "anthropic")).toBe(200000);
    expect(getContextWindow("x", "y")).toBe(32768);
    expect(getContextWindow()).toBe(32768);
  });
});

