const MODES = new Set([
  "default",
  "acceptEdits",
  "auto",
  "bypassPermissions",
  "dontAsk",
  "plan",
]);

function modeState(conv) {
  return {
    requested: conv.mode || "default",
    effective: conv.effectiveMode || null,
    status: conv.modeStatus || "pending",
    policyRevision: conv.policyRevision || null,
    reason: conv.modeError || "",
  };
}

/** ACK is display evidence, never a replacement for the CLI permission gate. */
function acceptModeAcknowledgement(conv, event) {
  const ack = event?.permission_mode_state;
  if (
    ack &&
    (ack.correlation_id !== conv.modeRequestId ||
      event.session_id !== conv.sessionId)
  )
    return false;
  if (
    !ack ||
    ack.correlation_id !== conv.modeRequestId ||
    ack.requested !== conv.mode ||
    !MODES.has(ack.effective) ||
    typeof ack.policy_revision !== "string" ||
    !/^[a-f0-9]{16,64}$/.test(ack.policy_revision)
  ) {
    conv.modeStatus = "unconfirmed";
    conv.modeError =
      "The CLI has not confirmed its effective approval mode. Update the CLI if needed.";
    return false;
  }
  conv.effectiveMode = ack.effective;
  conv.policyRevision = ack.policy_revision;
  conv.modeStatus = "effective";
  conv.modeError = "";
  return true;
}

module.exports = { modeState, acceptModeAcknowledgement };

/**
 * Panel approval-mode selector (`/auto` · `/bypass` · `/normal`) — Claude-Code
 * auto-accept/bypass parity. Covers the pure arg builder, the conversation
 * model field, and the ChatViewProvider orchestration (mode set → child
 * restart → the next spawn carries `--permission-mode`). All headless in the
 * CLI suite (no vscode host; injected createSession + fake window).
 */
import { describe, it, expect } from "vitest";
import { ChatViewProvider } from "../../../vscode-extension/src/chat/chat-view.js";
import {
  buildSessionArgs,
  PERMISSION_MODES,
} from "../../../vscode-extension/src/chat/chat-events.js";
import { ConversationManager } from "../../../vscode-extension/src/chat/conversation-manager.js";
import { createModeStatusBar } from "../../../vscode-extension/src/ui/status-bar.js";
import * as slashMod from "../../../vscode-extension/src/chat/slash-commands.js";

const slash = slashMod.default || slashMod;

describe("buildSessionArgs — permission mode", () => {
  it("emits --permission-mode for the hands-off modes", () => {
    expect(buildSessionArgs({ mode: "acceptEdits" })).toEqual([
      "--permission-mode",
      "acceptEdits",
    ]);
    expect(buildSessionArgs({ mode: "bypassPermissions" })).toEqual([
      "--permission-mode",
      "bypassPermissions",
    ]);
  });

  it("omits the flag for default / unset / unknown modes", () => {
    expect(buildSessionArgs({})).toEqual([]);
    expect(buildSessionArgs({ mode: "default" })).toEqual([]);
    expect(buildSessionArgs({ mode: "nonsense" })).toEqual([]);
    expect(buildSessionArgs({ mode: "" })).toEqual([]);
  });

  it("composes mode after model/provider/resume", () => {
    expect(
      buildSessionArgs({
        provider: "ollama",
        model: "qwen2.5:7b",
        resume: "sess-1",
        mode: "acceptEdits",
      }),
    ).toEqual([
      "--provider",
      "ollama",
      "--model",
      "qwen2.5:7b",
      "--resume",
      "sess-1",
      "--permission-mode",
      "acceptEdits",
    ]);
  });

  it("PERMISSION_MODES is the allow-list (no 'default')", () => {
    expect(PERMISSION_MODES.has("acceptEdits")).toBe(true);
    expect(PERMISSION_MODES.has("bypassPermissions")).toBe(true);
    expect(PERMISSION_MODES.has("plan")).toBe(true);
    expect(PERMISSION_MODES.has("default")).toBe(false);
  });
});

describe("ConversationManager — mode field", () => {
  it("defaults to 'default' and round-trips through setMode + list()", () => {
    const cm = new ConversationManager({});
    const c = cm.create({});
    expect(c.mode).toBe("default");
    cm.setMode(c.id, "acceptEdits");
    expect(cm.get(c.id).mode).toBe("acceptEdits");
    expect(cm.list()[0].mode).toBe("acceptEdits");
    // falsy → back to default (never an empty mode)
    cm.setMode(c.id, "");
    expect(cm.get(c.id).mode).toBe("default");
  });
});

// --- ChatViewProvider._setMode orchestration ---

function makeMemento(seed = {}) {
  const m = new Map(Object.entries(seed));
  return {
    get: (k) => (m.has(k) ? m.get(k) : null),
    update: (k, v) => m.set(k, v),
  };
}

function makeProvider() {
  const posted = [];
  const spawns = [];
  const commandCalls = [];
  const vscode = {
    commands: {
      executeCommand(id) {
        commandCalls.push(id);
        return Promise.resolve();
      },
    },
    window: {},
    workspace: {
      workspaceFolders: [{ uri: { fsPath: "/ws" } }],
      getConfiguration: () => ({ get: () => undefined }),
    },
  };
  const createSession = (cfg) => {
    const s = {
      cfg,
      running: true,
      send: () => true,
      sendEvent: () => true,
      stop() {
        this.running = false;
      },
      stopAndWait() {
        this.stop();
        return Promise.resolve();
      },
    };
    spawns.push(s);
    return s;
  };
  const provider = new ChatViewProvider(vscode, {
    deps: { createSession },
    state: makeMemento({}),
  });
  provider.view = {
    webview: { postMessage: (msg) => (posted.push(msg), Promise.resolve()) },
  };
  return { provider, posted, spawns, commandCalls };
}

const lastPost = (posted) => posted[posted.length - 1];

describe("ChatViewProvider — approval mode", () => {
  function ack(session, overrides = {}) {
    session.cfg.onEvent({
      type: "system",
      subtype: "init",
      session_id: session.cfg.args[session.cfg.args.indexOf("--resume") + 1],
      permission_mode_state: {
        correlation_id: session.cfg.env.CC_IDE_MODE_REQUEST_ID,
        requested: session.cfg.env.CC_IDE_REQUESTED_MODE,
        effective: session.cfg.env.CC_IDE_REQUESTED_MODE,
        policy_revision: "a".repeat(16),
        ...overrides,
      },
    });
  }

  it("waits for a correlated runtime ACK, including a policy override", () => {
    const { provider, spawns } = makeProvider();
    provider._setMode("bypassPermissions");
    provider._handleMessage({ type: "send", text: "hi" });
    const conv = provider._activeConv();
    expect(conv.modeStatus).toBe("pending");
    ack(spawns[0], { correlation_id: "wrong-child" });
    expect(conv.effectiveMode).toBeUndefined();
    ack(spawns[0], { effective: "default" });
    expect(conv).toMatchObject({
      mode: "bypassPermissions",
      effectiveMode: "default",
      modeStatus: "effective",
      policyRevision: "a".repeat(16),
    });
  });

  it("does not respawn while the old process is stopping or after stop failure", async () => {
    const { provider, spawns, posted } = makeProvider();
    provider._handleMessage({ type: "send", text: "hi" });
    ack(spawns[0], { effective: "bypassPermissions" });
    let rejectStop;
    spawns[0].stopAndWait = () =>
      new Promise((_resolve, reject) => {
        rejectStop = reject;
      });
    provider._setMode("default");
    provider._handleMessage({ type: "send", text: "during stop" });
    expect(spawns).toHaveLength(1);
    expect(provider._activeConv().effectiveMode).toBe("bypassPermissions");
    rejectStop(new Error("taskkill failed"));
    await Promise.resolve();
    expect(provider._activeConv().modeStatus).toBe("failed");
    provider._handleMessage({ type: "send", text: "after failure" });
    expect(spawns).toHaveLength(1);
    expect(posted.some((m) => m.text?.includes("taskkill failed"))).toBe(true);
  });

  it("ignores old child ACKs, reports older CLI and synchronous spawn failure", async () => {
    const { provider, spawns } = makeProvider();
    provider._handleMessage({ type: "send", text: "hi" });
    spawns[0].cfg.onEvent({ type: "system", subtype: "init" });
    expect(provider._activeConv().modeStatus).toBe("unconfirmed");
    provider._setMode("acceptEdits");
    ack(spawns[0]);
    expect(provider._activeConv().modeStatus).toBe("pending");
    await Promise.resolve();
    provider._createSession = () => {
      throw new Error("spawn denied");
    };
    provider._handleMessage({ type: "send", text: "retry" });
    expect(provider._activeConv()).toMatchObject({
      effectiveMode: null,
      modeStatus: "failed",
      modeError: "spawn denied",
    });
  });

  it("sets the active conversation's mode and acknowledges (no live child)", () => {
    const { provider, posted } = makeProvider();
    provider._handleMessage({ type: "mode", mode: "acceptEdits" });
    expect(provider._activeConv().mode).toBe("acceptEdits");
    expect(lastPost(posted)).toMatchObject({
      kind: "info",
      text: expect.stringContaining("auto-accept edits"),
    });
    expect(lastPost(posted).text).toContain("waiting for CLI confirmation");
    expect(provider._activeConv().effectiveMode).toBeUndefined();
  });

  it("stops the live child so the next turn respawns with the new mode", async () => {
    const { provider, posted, spawns } = makeProvider();
    // First turn spawns a child in default mode (no flag).
    provider._handleMessage({ type: "send", text: "hi" });
    expect(spawns).toHaveLength(1);
    expect(spawns[0].cfg.args).not.toContain("--permission-mode");
    expect(spawns[0].running).toBe(true);

    // Switch to bypass: the live child is stopped, ack mentions next message.
    provider._handleMessage({ type: "mode", mode: "bypassPermissions" });
    expect(spawns[0].running).toBe(false);
    expect(lastPost(posted).text).toContain("next message");
    await Promise.resolve();

    // Next turn respawns carrying the flag, resuming nothing new (same conv).
    provider._handleMessage({ type: "send", text: "again" });
    expect(spawns).toHaveLength(2);
    expect(spawns[1].cfg.args).toEqual(
      expect.arrayContaining(["--permission-mode", "bypassPermissions"]),
    );
  });

  it("rejects an unknown mode without touching the conversation", () => {
    const { provider, posted } = makeProvider();
    provider._handleMessage({ type: "mode", mode: "wat" });
    expect(provider._activeConv().mode).toBe("default");
    expect(lastPost(posted)).toMatchObject({
      kind: "info",
      text: expect.stringContaining("unknown mode"),
    });
  });
});

describe("ChatViewProvider — Configure LLM reloads running children", () => {
  it("runs the wizard then restarts the live child so it picks up new config", async () => {
    const { provider, posted, spawns, commandCalls } = makeProvider();
    // A child is already running with the OLD (broken) config.
    provider._handleMessage({ type: "send", text: "hi" });
    expect(spawns).toHaveLength(1);
    expect(spawns[0].running).toBe(true);

    // Configure LLM: opens the wizard, then (once it closes) stops the child.
    provider._handleMessage({ type: "configureLlm" });
    expect(commandCalls).toContain("chainlesschain.llm.configure");
    // Reload is chained off the wizard promise — flush microtasks.
    await Promise.resolve();
    await Promise.resolve();
    await Promise.resolve();
    expect(spawns[0].running).toBe(false);
    expect(lastPost(posted)).toMatchObject({
      kind: "info",
      text: expect.stringContaining("LLM config updated"),
    });
    expect(lastPost(posted).text).toContain("next message");

    // Next turn respawns a FRESH child (reads the updated config.json).
    provider._handleMessage({ type: "send", text: "again" });
    expect(spawns).toHaveLength(2);
    expect(spawns[1].running).toBe(true);
  });

  it("acknowledges with no 'next message' qualifier when no child is running", async () => {
    const { provider, posted, commandCalls } = makeProvider();
    provider._handleMessage({ type: "configureLlm" });
    expect(commandCalls).toContain("chainlesschain.llm.configure");
    await Promise.resolve();
    await Promise.resolve();
    expect(lastPost(posted)).toMatchObject({
      kind: "info",
      text: expect.stringContaining("LLM config updated"),
    });
    expect(lastPost(posted).text).not.toContain("next message");
  });
});

describe("createModeStatusBar — render", () => {
  function makeStatusVscode() {
    const item = {
      text: "",
      tooltip: "",
      backgroundColor: "UNSET",
      command: null,
      show: () => {},
      dispose: () => {},
    };
    const vscode = {
      StatusBarAlignment: { Right: 2 },
      ThemeColor: class ThemeColor {
        constructor(id) {
          this.id = id;
        }
      },
      l10n: {
        t: (m, ...a) =>
          String(m).replace(/\{(\d+)\}/g, (x, i) =>
            a[i] != null ? String(a[i]) : x,
          ),
      },
      window: { createStatusBarItem: () => item },
    };
    return { vscode, item };
  }

  it("highlights bypass with the warning background", () => {
    const { vscode, item } = makeStatusVscode();
    createModeStatusBar(vscode).render("bypassPermissions");
    expect(item.text).toContain("bypass");
    expect(item.backgroundColor).toBeInstanceOf(vscode.ThemeColor);
    expect(item.backgroundColor.id).toBe("statusBarItem.warningBackground");
  });

  it("shows auto-accept and normal without a warning background", () => {
    const { vscode, item } = makeStatusVscode();
    const bar = createModeStatusBar(vscode);
    bar.render("acceptEdits");
    expect(item.text).toContain("auto-accept");
    expect(item.backgroundColor).toBeUndefined();
    bar.render("default");
    expect(item.text).toContain("approvals");
    expect(item.backgroundColor).toBeUndefined();
  });

  it("never labels a pending/failed tightening as normal approvals", () => {
    const { vscode, item } = makeStatusVscode();
    const bar = createModeStatusBar(vscode);
    bar.render({
      requested: "default",
      effective: "bypassPermissions",
      status: "pending",
    });
    expect(item.text).toContain("unconfirmed");
    expect(item.tooltip).toContain("bypassPermissions");
    expect(item.backgroundColor).toBeInstanceOf(vscode.ThemeColor);
    bar.render({
      requested: "default",
      effective: "bypassPermissions",
      status: "failed",
      reason: "stop timeout",
    });
    expect(item.text).toContain("failed");
    expect(item.tooltip).toContain("stop timeout");
  });
});

describe("ChatViewProvider — status-bar mode indicator wiring", () => {
  it("re-renders the indicator on mode change and tab refresh", () => {
    const { provider } = makeProvider();
    const renders = [];
    provider._modeStatus = {
      render: (m) => renders.push(m),
      item: { dispose: () => {} },
    };
    // mode change → render with the new mode
    provider._handleMessage({ type: "mode", mode: "bypassPermissions" });
    expect(renders).toContainEqual(
      expect.objectContaining({
        requested: "bypassPermissions",
        effective: null,
        status: "pending",
      }),
    );
    // a tab refresh re-renders the active conversation's current mode
    renders.length = 0;
    provider._postTabs();
    expect(renders).toEqual([
      expect.objectContaining({
        requested: "bypassPermissions",
        effective: null,
        status: "pending",
      }),
    ]);
  });

  it("_updateModeStatus is inert when no status item exists (test mock)", () => {
    const { provider } = makeProvider();
    expect(provider._modeStatus).toBeUndefined();
    // must not throw despite window.createStatusBarItem being absent
    expect(() => provider._updateModeStatus()).not.toThrow();
  });
});

describe("slash-commands menu — mode entries", () => {
  it("lists /auto, /bypass, /normal and filters them by prefix", () => {
    const names = slash.SLASH_COMMANDS.map((r) => r[0]);
    expect(names).toEqual(
      expect.arrayContaining(["/auto", "/bypass", "/normal"]),
    );
    expect(slash.filterSlashCommands("auto").map((r) => r[0])).toEqual([
      "/auto",
    ]);
    expect(slash.filterSlashCommands("b").map((r) => r[0])).toContain(
      "/bypass",
    );
  });
});

